files.ergostat.yaml:
name: routes
include: [factory.yaml, intake.yaml]
systems:
  factory: {description: makes things}
  intake: {within: factory, description: takes work in}
  qa: {within: factory, description: checks the work}
  delivery: {within: factory, description: ships it}
projections:
  ticket: {fields: {state: {values: [new, shipped]}}, system: intake}
  note: {fields: {state: {values: [open]}}, system: qa}
  report: {query: "glob(key, 'report/*')", fields: {state: {values: [sent]}}, system: delivery}
  run: {query: "glob(key, 'run/*')", fields: {state: {values: [going]}}}
stocks:
  arrived: {system: intake, unit: tickets, sensor: {projection: ticket, state: new}}
  shipped: {system: delivery, unit: tickets, sensor: {projection: ticket, state: shipped}}
  notes-open: {system: qa, unit: notes, sensor: {projection: note, state: open}}
  reports-sent: {unit: reports, sensor: {projection: report, state: sent}}
  runs: {unit: runs, sensor: {projection: run, state: going}}
flows:
  take-in: {system: intake, to: arrived}
goals:
  full: {system: intake, stock: arrived, hold: "<= 50"}
blocks:
  gate: {system: intake, type: program, run: echo 1, in: goal.full, out: flow.take-in, agent: ops}
agents:
  ops: {kind: program}
dashboards:
  weekly:
    panels:
      - {panel: chart, refs: stock.runs}

name: order
include: [factory.yaml]
systems:
  factory: {description: makes things}
  intake: {within: factory, description: takes work in}
  ticket: {within: factory, description: a subsystem named as a projection}
  work: {within: factory, description: named as a top-level projection}
projections:
  ticket: {fields: {state: {values: [new]}}, system: intake}
  work: {query: "glob(key, 'work/*')", fields: {state: {values: [a]}}}
stocks:
  arrived: {system: intake, unit: tickets, sensor: {projection: ticket, state: new}}
  seen: {unit: tickets, sensor: {projection: ticket, state: new}}
  doing: {unit: things, sensor: {projection: work, state: a}}
  held: {system: work, unit: things, sensor: {manual: true}}
flows:
  pull: {system: intake, from: doing, to: arrived}

name: unreachable
include: [factory.yaml]
systems:
  factory: {}
  review: {within: factory}
  goals: {within: factory}
  api: {}
projections:
  events: {query: "glob(key, 'ev/*')", fields: {state: {values: [a]}}}
  static: {query: "glob(key, 'st/*')", fields: {state: {values: [a]}}}
stocks:
  seen: {unit: events, sensor: {projection: events, state: a}}
  waiting: {system: review, unit: things, sensor: {manual: true}}
